{
  const reader = readableStream.getReader();
  let done = false;
  try {
    while (true) {
      const result = await reader.read();
      if (result.done) {
        done = true;
        return;
      }
      yield result.value!;
    }
  } finally {
    try {
      if (!done) {
        await reader.cancel?.();
      }
    } finally {
      reader.releaseLock();
    }
  }
}

