{
  const reader = readableStream.getReader();
  let exhausted = false;
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) {
        exhausted = true;
        return;
      }
      yield value!;
    }
  } finally {
    try {
      if (!exhausted && isFunction(reader.cancel)) {
        await reader.cancel();
      }
    } finally {
      reader.releaseLock();
    }
  }
}

{
  if (!input) {
    throw new Error('Iterable cannot be null');
  }
  return new Observable<T>((subscriber) => {
    let iterator: AsyncIterator<T> | undefined;
    let stopped = false;
    let finished = false;
    let returned = false;
    let pending = false;

    const returnIterator = () => {
      stopped = true;
      if (!finished && iterator && !returned) {
        returned = true;
        try {
          const result = iterator.return?.();
          if (result) {
            Promise.resolve(result).catch(() => undefined);
          }
        } catch {
          // An early unsubscribe cannot deliver an iterator return error.
        }
      }
    };

    const fail = (error: any) => {
      if (stopped || finished) {
        return;
      }
      finished = true;
      subscriber.error(error);
    };

    const scheduleNext = () => {
      if (stopped || subscriber.closed || pending) {
        return;
      }
      executeSchedule(subscriber, scheduler, () => {
        if (stopped || subscriber.closed || pending) {
          return;
        }
        pending = true;
        let nextResult: PromiseLike<IteratorResult<T>>;
        try {
          nextResult = iterator!.next();
        } catch (error) {
          pending = false;
          fail(error);
          return;
        }
        Promise.resolve(nextResult)
          .then(
            (result) => {
              pending = false;
              if (stopped || subscriber.closed) {
                return;
              }
              if (result.done) {
                finished = true;
                subscriber.complete();
              } else {
                subscriber.next(result.value);
                scheduleNext();
              }
            },
            fail
          )
          .catch(fail);
      });
    };

    subscriber.add(returnIterator);
    executeSchedule(subscriber, scheduler, () => {
      if (stopped || subscriber.closed) {
        return;
      }
      iterator = input[Symbol.asyncIterator]();
      scheduleNext();
    });
  });
}

